import bpy,os
B=os.path.abspath(os.path.join(os.path.dirname(__file__), '../..'));OUT=os.path.join(B,'animations');names=['Stretch','Idle','Breathe','Wave','Celebrate','Walk-off','Walk-back']
bpy.ops.wm.open_mainfile(filepath=os.path.join(OUT,names[0],'Pip.blend'))
for name in names[1:]:
 with bpy.data.libraries.load(os.path.join(OUT,name,'Pip.blend'),link=False) as (src,dest):dest.scenes=src.scenes
bpy.context.window.scene=bpy.data.scenes['Stretch']
text=bpy.data.texts.new('Pip movement guide');text.write('''PIP — FRESH MOVEMENT LIBRARY\n\nChoose a movement from the Scene dropdown at the top right of Blender.\nPress Space to play. Each scene has its own controls and action data.\n\nStretch: frames 1–300, ten seconds. Based on all eight poses in the supplied reference sheet.\nIdle: 1–180, six seconds. Subtle breathing and blinks.\nBreathe: 1–240, eight seconds. Hands settle near the belly, inhale, exhale, release.\nWave: 1–120, four seconds. Small wrist-led greeting.\nCelebrate: 1–90, three seconds. Quiet two-arm cheer.\nWalk-off / Walk-back: 1–165 each, five and a half seconds.\n\nControls: CTRL • placement moves the entire character; CTRL • body lean and stretch\ncontrols the torso and face. Shoulder, elbow and wrist controls drive Bezier limbs.\nHip, knee and ankle controls drive the legs. Mitten and foot objects have keyed\ntransforms. CTRL • eyes and expression has a keyed blink property.\n\nThe last +1 frame is a loop-boundary key; export only through each scene's end frame.\nIdle, Stretch, Breathe, Wave and Celebrate loop. The two walking clips are transitions.\n\nAll controls have dense editable keys at 30 fps. No external handlers are needed.\nArms intentionally lengthen and shoulders rise during the overhead stretch to match\nthe stylised reference. The original approved neutral model is preserved separately.\n''')
bpy.ops.wm.save_as_mainfile(filepath=os.path.join(OUT,'Pip-movements.blend'),compress=True)
print('MASTER SAVED',[(s.name,s.frame_end) for s in bpy.data.scenes],flush=True)
